"""Lote 14 · archivos raíz (aplicacion, configuracion, consola_agente, servidor_datos y __init__): créditos de Piña y Jara, documentación y nombres en español.

Ejecutar desde la raíz del proyecto:   python instalar_encabezados_archivos_raiz.py
Idempotente, sin .bak. No instala nada si algún archivo difiere de la versión esperada.
"""
import base64, hashlib, io, json, os, sys, zipfile

PRE = {'__init__.py': '0f87090334567733a2b1c7d82cb465ed36936cede83e08c1840fdce4990c8228', 'aplicacion.py': '6888f271b212eee16761efcecd8149ffc2523f3b07fa6869bd959c0388657c5d', 'configuracion.py': 'fbd616917b500387c9772fe8f305bd415251f1dcf27e882756dd7c20cdbac511', 'consola_agente.py': '8aa031ae59ac44910cabf3f86ffa74a5372d6c2525b96d303d621b09972e2e5e', 'nucleo_agente/llm/cliente.py': '39bed88439646a525fa27cf94dc877e0363b5ce553db3383da43f1ab236555e7', 'servidor_datos.py': 'b3a4d833c587a04f99569c954e6cec97dfdb3cae3ec826702ebd6a0cb0a57f1c'}
ARCHIVOS = ["__init__.py", "aplicacion.py", "configuracion.py", "consola_agente.py", "nucleo_agente/llm/cliente.py", "servidor_datos.py"]
ZIP_B64 = ""


def norm(b):
    return b.replace(b"\r\n", b"\n")


def main():
    z = zipfile.ZipFile(io.BytesIO(base64.b64decode(ZIP_B64)))
    nuevos = {f: norm(z.read(f)) for f in ARCHIVOS}
    if all(os.path.exists(f) and norm(open(f, "rb").read()) == nuevos[f] for f in ARCHIVOS):
        print("Ya estaba instalado: no hay nada que hacer.")
        return
    problemas = []
    for f, h in PRE.items():
        if h is None:
            if os.path.exists(f):
                problemas.append("ya existe " + f)
        elif not os.path.exists(f):
            problemas.append("falta " + f)
        elif hashlib.sha256(norm(open(f, "rb").read())).hexdigest() != h:
            problemas.append(f + " difiere de la versión esperada (¿cambios sin subir?)")
    if problemas:
        print("No se instaló nada:")
        for p in problemas:
            print("  -", p)
        sys.exit(1)
    for f in ARCHIVOS:
        datos = nuevos[f]
        os.makedirs(os.path.dirname(f) or ".", exist_ok=True)
        if os.path.exists(f) and b"\r\n" in open(f, "rb").read():
            datos = datos.replace(b"\n", b"\r\n")
        with open(f, "wb") as fh:
            fh.write(datos)
    print("Listo: %d archivos actualizados." % len(ARCHIVOS))


if __name__ == "__main__":
    main()
